#define DECL_TYPE_CHECK(ctypelower, CTYPE) \
    template <class> struct is_##ctypelower : std::false_type {};\
    template <class IMPL, class NEXT_TYPE> struct is_##ctypelower<CTYPE<IMPL, NEXT_TYPE>> : std::true_type {};

